(() => {
  const tracks = {
    lift: [
      [0], [.23], [.34], [.69], [.88], [.96], [1], [1]
    ],
    leftNearEye: [
      [0,0,0,0,0], [-1.5,-3.6,-3,0,-.3], [-.5,-5.5,-4,0,-.5],
      [9.3,-15.1,3,.35,-1.3], [12.2,-20.6,8,.7,-1.8],
      [11.4,-25,10,.6,-2], [10.4,-27,11,.55,-2], [10.4,-27,11,.55,-2]
    ],
    leftFarEye: [
      [0,0,1], [-3.4,-5.5,.95], [-6.4,-8.4,.92], [-.6,-22,.45],
      [-2.9,-27.5,.31], [-5.5,-30.3,.24], [-7,-32,.2], [-7,-32,.2]
    ],
    leftMouth: [
      [0,0,0,0,.69], [-3.2,-4.8,1,0,.84], [-2.6,-6.2,1,0,.94],
      [6.6,-18.2,0,1,1], [8,-24.4,0,1,1],
      [7.4,-28.1,0,1,1], [7.1,-29.3,0,1,1], [7.1,-29.3,0,1,1]
    ],
    belly: [
      [1,1], [1.072,1.122], [1.063,1.095], [1.096,1.19],
      [1.115,1.238], [1.128,1.267], [1.135,1.31], [1.135,1.31]
    ],
    writing: [
      [0,0,0,0], [-7,-1.1,-8,1], [-12.1,-3.5,-13,1],
      [-18.2,-7.3,-17,2], [-21.6,-9.8,-20,3],
      [-23,-10.5,-25,4], [-23.5,-10.4,-25,4], [-23.4,-10.4,-25,4]
    ],
    resting: [
      [0,0], [-.4,-.2], [-.8,-.5], [.2,-2.8],
      [.5,-4.7], [-1.2,-4.3], [-1.4,-5.7], [-1.4,-5.7]
    ],
    rightHead: [
      [0,0,0,0,0,0,1], [-8,1,0,1,.6,2.3,1.02], [-9,.5,0,1,.3,1.9,.97],
      [-8,.4,0,.2,0,.5,.89], [-7,-.4,-1,-.3,-.3,.2,.89],
      [-6,-1.4,-2,-2.1,-.45,-1.9,.84], [-5.8,-2.1,-2,-2.6,-.6,-2.1,.87],
      [-5.5,-2.6,-2.3,-2.3,-.7,-1.8,.89]
    ],
    farHand: [
      [0,0,0], [-4,-2,-3], [-7.3,-4.5,-6], [-10.5,-9,-9],
      [-13.2,-11.5,-10], [-15.7,-10.8,-9], [-16.2,-10.2,-9], [-16.2,-10.2,-9]
    ],
    rubbing: [
      [0,0,0], [-7.6,-3.8,3], [-17.9,1.4,-3], [-13,-5.8,1],
      [-15.8,-4.7,-2], [-18.8,-.1,-3], [-12.7,-7.2,2], [-15,-5.6,0]
    ]
  };

  const paths = {
    leftHead: "M 16 113 C 19 101 21 88 26 78 C 32 65 45 54 58 52 C 71 50 82 55 90 65 C 98 75 100 85 97 94 C 95 100 91 103 91 109 C 92 116 96 121 101 127 C 87 141 37 146 14 131 C 11 127 13 120 16 113 Z",
    raisedHead: "M 3 111 C 2 95 5 75 13 59 C 20 43 33 36 49 35 C 64 34 78 42 83 52 C 88 61 87 70 84 78 C 82 84 76 88 76 96 C 78 107 91 115 100 128 C 86 141 36 145 10 134 C 4 129 3 120 3 111 Z",
    leftTorso: "M 12 120 C 19 108 22 92 35 87 C 49 80 72 84 83 95 C 92 104 92 114 103 126 C 114 138 120 151 124 167 C 127 178 127 190 120 196 C 115 200 108 198 100 197 C 90 195 83 199 77 201 C 67 198 57 199 48 203 C 39 207 29 212 19 210 C 4 208 -5 193 -6 179 C -8 158 0 135 12 120 Z",
    raisedTorso: "M -3 119 C 3 105 9 88 25 81 C 43 74 61 77 72 90 C 80 100 85 109 96 122 C 109 135 117 148 123 165 C 126 177 126 188 119 195 C 114 200 107 198 99 197 C 88 195 84 200 77 201 C 67 198 57 199 48 203 C 39 207 29 212 19 210 C 4 208 -5 193 -6 179 C -9 155 -9 132 -3 119 Z",
    relaxedMouth: "M 62.9 108.4 C 65.3 109.4 68.1 111.7 71.3 111.9 C 74.5 112.1 77.4 111.4 79.7 110.3 C 75.3 114.9 67.8 114.3 62.9 108.4 Z",
    smilingMouth: "M 60 107.4 C 64 109.8 67.2 111.1 71 110.8 C 75 110.5 78.1 108.7 80.6 106.4 C 77.2 114.3 65.4 115.1 60 107.4 Z",
    openMouth: "M 61 110.6 C 63.2 109.2 66.8 109 70.8 108.7 C 74.5 108.4 77.4 107.7 79.1 106.7 C 78.4 111.8 67.3 114.7 61 110.6 Z",
    leftFarArm: "M 98 128 C 109 132 113 140 119 152 C 124 162 126 176 123 188 L 107 193 C 112 182 110 173 106 161 C 103 152 95 144 95 136 Z",
    writingArm: "M 11 126 C 3 135 -1 149 -3 162 C -5 178 -5 190 2 200 C 8 208 18 213 28 211 C 34 210 38 206 36 201 C 34 197 26 195 22 190 C 18 185 18 179 20 170 C 22 161 26 152 25 144 C 24 137 19 128 11 126 Z",
    writingShadow: "M 14 153 C 18 145 24 141 28 145 C 28 157 20 174 22 185 C 23 190 28 195 32 198 L 23 204 C 15 200 12 194 12 186 C 11 176 11 165 14 153 Z",
    writingEdge: "M 0 197 C 6 205 13 207 26 207",
    rightTorso: "M 123 99 C 127 84 133 70 148 65 C 161 60 180 65 191 78 C 198 86 201 95 206 103 C 214 116 223 127 230 141 C 238 155 243 171 242 186 C 233 188 227 184 218 186 C 206 188 193 190 181 193 C 164 197 148 188 136 180 C 122 170 114 154 115 137 C 115 124 118 111 123 99 Z",
    rightFarArm: "M 134 104 C 123 104 117 110 107 114 C 102 117 98 115 95 116 L 96 130 C 102 138 112 145 122 147 C 132 143 139 134 140 121 Z",
    embracingArm: "M 103 160 C 115 156 124 153 137 150 C 154 145 168 140 179 129 C 186 122 189 115 193 107 C 196 101 202 99 206 106 C 212 116 211 128 205 141 C 199 155 190 165 177 172 C 160 181 138 186 121 185 C 111 184 104 181 101 174 C 99 169 100 164 103 160 Z",
    embracingShadow: "M 105 163 C 120 155 139 157 160 148 C 175 142 186 135 195 119 L 205 129 C 201 147 189 162 171 173 C 154 185 134 190 115 190 C 106 188 102 183 101 177 Z",
    embracingEdge: "M 123 184 C 146 184 177 174 194 156"
  };

  const clamp = x => Math.min(1, Math.max(0, x));
  const mix = (a, b, u) => a + (b - a) * u;
  const round = x => Math.round(x * 1000) / 1000;
  const set = (id, name, value) => document.getElementById(id).setAttribute(name, value);
  const move = (id, x, y, rest = "") =>
    set(id, "transform", `translate(${round(x)} ${round(y)}) ${rest}`);
  const draw = (id, d) => set(id, "d", d);

  function morph(from, to, amount) {
    const coordinates = to.match(/-?\d+(?:\.\d+)?/g).map(Number);
    let index = 0;
    return from.replace(/-?\d+(?:\.\d+)?/g, value =>
      round(mix(Number(value), coordinates[index++], amount))
    );
  }

  function bend(path, map) {
    return path.replace(/(-?\d+(?:\.\d+)?) (-?\d+(?:\.\d+)?)/g, (_, x, y) => {
      const [nextX, nextY] = map(Number(x), Number(y));
      return `${round(nextX)} ${round(nextY)}`;
    });
  }

  function tangent(before, after) {
    return before * after <= 0 ? 0 : 2 * before * after / (before + after);
  }

  function render(t) {
    const time = ((t % 1500) + 1500) % 1500;
    const i = Math.min(7, Math.floor(time / 200));
    const u = time / 200 - i;
    function sample(track) {
      if (i === 7 || u === 0) return track[i];
      const u2 = u * u;
      const u3 = u2 * u;
      return track[i].map((a, j) => {
        const b = track[i + 1][j];
        const delta = b - a;
        const start = tangent(a - track[Math.max(0, i - 1)][j], delta);
        const end = tangent(delta, track[Math.min(7, i + 2)][j] - b);
        return a + (3 * u2 - 2 * u3) * delta +
          (u3 - 2 * u2 + u) * start + (u3 - u2) * end;
      });
    }

    const [lift] = sample(tracks.lift);
    draw("left-head-profile", morph(paths.leftHead, paths.raisedHead, lift));
    draw("left-torso-profile", morph(paths.leftTorso, paths.raisedTorso, lift));
    set("left-face-color", "cx", 57 - 8 * lift);
    set("left-face-color", "cy", 53 - 17 * lift);
    set("left-coat", "cy", 125 - 6 * lift);
    move("left-crown-highlight", -8 * lift, -17 * lift);
    move("left-cheek-shading", -6 * lift, -11 * lift);
    const [bellyX, bellyY] = sample(tracks.belly);
    set("left-belly", "transform",
      `translate(106 202) scale(${bellyX} ${bellyY}) translate(-106 -202)`);

    const [nearX, nearY, eyeAngle, pupilX, pupilY] = sample(tracks.leftNearEye);
    move("left-outer-eye", nearX, nearY, `rotate(${eyeAngle} 50.7 89.3)`);
    move("left-outer-pupil", pupilX, pupilY);
    const [innerX, innerY, innerWidth] = sample(tracks.leftFarEye);
    move("left-inner-eye", innerX, innerY,
      `translate(90 92.5) scale(${innerWidth} 1) translate(-90 -92.5)`);
    const [mouthX, mouthY, smile, open, mouthOpacity] = sample(tracks.leftMouth);
    move("left-mouth", mouthX, mouthY);
    const mouth = morph(paths.relaxedMouth, paths.smilingMouth, smile);
    draw("left-mouth-profile", morph(mouth, paths.openMouth, open));
    set("left-mouth-ink", "opacity", mouthOpacity);

    const [restX, restY] = sample(tracks.resting);
    move("left-resting-hand", restX, restY);
    draw("left-far-sleeve", bend(paths.leftFarArm, (x, y) => {
      const weight = clamp((192 - y) / 64);
      return [x - 7 * lift * weight, y - 8 * lift * weight];
    }));

    const [writeX, writeY, pencilAngle, handAngle] = sample(tracks.writing);
    const flexWritingArm = (x, y) => {
      const weight = Math.pow(clamp((y - 139) / 65), 1.2);
      return [x + writeX * weight, y + writeY * weight];
    };
    draw("writing-arm-profile", bend(paths.writingArm, flexWritingArm));
    draw("writing-arm-shadow", bend(paths.writingShadow, flexWritingArm));
    draw("writing-arm-edge", bend(paths.writingEdge, flexWritingArm));
    move("writing-arm-light", writeX * .32, writeY * .3);
    move("left-wrist", writeX, writeY);
    set("left-pencil", "transform", `rotate(${pencilAngle} 35 198)`);
    set("left-writing-hand", "transform", `rotate(${handAngle} 34 201)`);

    const [headX, headY, rightEyeX, rightEyeY, rightMouthX, rightMouthY, mouthHeight] =
      sample(tracks.rightHead);
    move("right-head", headX, headY);
    move("right-inner-eye", rightEyeX, rightEyeY);
    move("right-mouth", rightMouthX, rightMouthY,
      `translate(0 90) scale(1 ${mouthHeight}) translate(0 -90)`);
    draw("right-torso-profile", bend(paths.rightTorso, (x, y) => {
      const weight = clamp((144 - y) / 65) * clamp((226 - x) / 96);
      return [x + headX * weight, y + headY * weight];
    }));

    const [farX, farY, farAngle] = sample(tracks.farHand);
    move("right-far-hand", farX, farY, `rotate(${farAngle} 99 112)`);
    draw("right-far-sleeve", bend(paths.rightFarArm, (x, y) => {
      const weight = clamp((139 - x) / 41);
      return [x + mix(.34 * headX, farX, weight), y + mix(headY, farY, weight)];
    }));

    const [rubX, rubY, rubAngle] = sample(tracks.rubbing);
    const flexEmbrace = (x, y) => {
      const weight = clamp((199 - x) / 84);
      return [x + rubX * weight, y + rubY * weight];
    };
    draw("embracing-arm-profile", bend(paths.embracingArm, flexEmbrace));
    draw("embracing-arm-shadow", bend(paths.embracingShadow, flexEmbrace));
    draw("embracing-arm-edge", bend(paths.embracingEdge, flexEmbrace));
    move("embracing-arm-light", rubX * .43, rubY * .48, "rotate(-24 157 150)");
    move("right-embracing-hand", rubX, rubY, `rotate(${rubAngle} 116 173)`);
  }

  window.nwb = { render };
  document.addEventListener("DOMContentLoaded", () => render(0), { once: true });
})();
</script>
